import{c as n,U as i,j as t,g as a,o as p,a6 as l,n as o}from"./chunks/framework.h4W4t1IS.js";const f=JSON.parse('{"title":"CCP et CRP - cohésion des packages","description":"","frontmatter":{"title":"CCP et CRP - cohésion des packages","status":"ready","tags":["qualite","all","packages"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"qualite/packages/ccp-crp.md","filePath":"qualite/packages/ccp-crp.md"}'),c={name:"qualite/packages/ccp-crp.md"},r={id:"frontmatter-title",tabindex:"-1"};function u(s,e,d,m,g,h){return i(),t("div",null,[a("h1",r,[p(l(s.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=o(`<p>Les principes <strong><a href="/420-w30-sf-po2/lexique.html#principe-de-fermeture-commune" class="lexicon-link" title="Principe de conception qui stipule que les classes qui changent pour les mêmes raisons devraient être regroupées dans le même module ou package.">CCP</a></strong> (<em>Common Closure Principle</em>) et <strong><a href="/420-w30-sf-po2/lexique.html#principe-de-reutilisation-commune" class="lexicon-link" title="Principe de conception qui stipule que les classes qui sont utilisées ensemble devraient être regroupées dans le même module ou package.">CRP</a></strong> (<em>Common Reuse Principle</em>) guident la décision de regrouper ou séparer des classes dans des packages.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Appliquer le CCP pour regrouper ce qui change ensemble</li><li>Appliquer le CRP pour éviter les dépendances inutiles</li><li>Utiliser ces deux principes pour prendre des décisions d&#39;organisation</li></ul></div><h2 id="ccp-principe-de-fermeture-commune" tabindex="-1">CCP - Principe de fermeture commune <a class="header-anchor" href="#ccp-principe-de-fermeture-commune" aria-label="Permalink to &quot;CCP - Principe de fermeture commune&quot;">​</a></h2><blockquote><p><strong>Les classes qui changent ensemble sont regroupées dans le même package.</strong></p></blockquote><p>Le CCP est le <a href="/420-w30-sf-po2/lexique.html#responsabilite-unique" class="lexicon-link" title="Principe SOLID qui stipule qu&#39;une classe ne devrait avoir qu&#39;une seule raison de changer.">SRP</a> appliqué aux packages : un package ne devrait avoir qu&#39;une seule raison de changer.</p><h3 id="exemple-bonne-application" tabindex="-1">Exemple - bonne application <a class="header-anchor" href="#exemple-bonne-application" aria-label="Permalink to &quot;Exemple - bonne application&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✓ Tout ce qui concerne la gestion des employés change ensemble</span></span>
<span class="line"><span>package ca.csfoy.po2.employe;</span></span>
<span class="line"><span>├── Employe.java</span></span>
<span class="line"><span>├── EmployeService.java</span></span>
<span class="line"><span>├── EmployeRepository.java</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Si les règles du domaine des employés changent, toutes ces classes sont affectées ensemble</span></span></code></pre></div><h3 id="exemple-mauvaise-organisation" tabindex="-1">Exemple - mauvaise organisation <a class="header-anchor" href="#exemple-mauvaise-organisation" aria-label="Permalink to &quot;Exemple - mauvaise organisation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✗ Employe et Configuration n&#39;ont aucune raison de changer ensemble</span></span>
<span class="line"><span>package ca.csfoy.po2.domaine;</span></span>
<span class="line"><span>├── Employe.java</span></span>
<span class="line"><span>├── ConfigurationApplication.java   ← ne change pas pour les mêmes raisons</span></span>
<span class="line"><span>├── UtilitaireEmail.java             ← ne change pas pour les mêmes raisons</span></span></code></pre></div><h2 id="crp-principe-de-reutilisation-commune" tabindex="-1">CRP - Principe de réutilisation commune <a class="header-anchor" href="#crp-principe-de-reutilisation-commune" aria-label="Permalink to &quot;CRP - Principe de réutilisation commune&quot;">​</a></h2><blockquote><p><strong>Les classes qui sont utilisées ensemble sont regroupées dans le même package.</strong></p></blockquote><p>Si je dois utiliser <code>ClasseA</code> d&#39;un package, je ne veux pas avoir à dépendre de <code>ClasseB</code> et <code>ClasseC</code> du même package si je n&#39;en ai pas besoin.</p><h3 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✗ Si on a besoin de StrategieAugmentation, on dépend aussi de tout le reste</span></span>
<span class="line"><span>package ca.csfoy.po2.services;</span></span>
<span class="line"><span>├── StrategieAugmentation.java   ← ce dont on a besoin</span></span>
<span class="line"><span>├── ServiceEmail.java            ← dépendance inutile</span></span>
<span class="line"><span>├── ServiceRapport.java          ← dépendance inutile</span></span>
<span class="line"><span>├── UtilitairePdf.java           ← dépendance inutile</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✓ Les interfaces de stratégies sont dans leur propre package</span></span>
<span class="line"><span>package ca.csfoy.po2.employe;</span></span>
<span class="line"><span>├── StrategieAugmentation.java</span></span>
<span class="line"><span>├── AugmentationPourcentage.java</span></span>
<span class="line"><span>├── AugmentationFixe.java</span></span></code></pre></div><h2 id="ccp-vs-crp-tension-naturelle" tabindex="-1">CCP vs CRP - tension naturelle <a class="header-anchor" href="#ccp-vs-crp-tension-naturelle" aria-label="Permalink to &quot;CCP vs CRP - tension naturelle&quot;">​</a></h2><p>Les deux principes sont en <strong>tension</strong> :</p><ul><li><strong>CCP</strong> dit : regroupe ce qui change ensemble → packages plus gros, cohésifs</li><li><strong>CRP</strong> dit : ne force pas à dépendre du superflu → packages plus petits, spécifiques</li></ul><p>En pratique, on cherche un équilibre selon le contexte :</p><table tabindex="0"><thead><tr><th>Contexte</th><th>Priorité</th></tr></thead><tbody><tr><td>Application</td><td>CCP - tout ce qui concerne un domaine</td></tr><tr><td>Bibliothèque réutilisable</td><td>CRP - pas de dépendances inutiles pour les clients</td></tr><tr><td>Composants internes</td><td>Les deux - <a href="/420-w30-sf-po2/lexique.html#cohesion" class="lexicon-link" title="Degré auquel les éléments d&#39;un module ou d&#39;une classe sont liés et travaillent ensemble pour accomplir une tâche spécifique. Une forte cohésion est souhaitable pour la clarté et la réutilisabilité du code.">cohésion</a> haute + <a href="/420-w30-sf-po2/lexique.html#couplage" class="lexicon-link" title="Degré de dépendance entre différentes parties d&#39;un système. Un couplage faible est souhaitable pour faciliter la maintenance et l&#39;évolution du code.">couplage</a> faible</td></tr></tbody></table><h2 id="application-pratique" tabindex="-1">Application pratique <a class="header-anchor" href="#application-pratique" aria-label="Permalink to &quot;Application pratique&quot;">​</a></h2><p>Pour chaque package, se poser les questions :</p><ol><li><strong>CCP</strong> : Ces classes ont-elles la même raison de changer?</li><li><strong>CRP</strong> : Un client qui utilise une classe de ce package a-t-il besoin des autres?</li><li><strong>Cohésion</strong> : Le rôle de ce package peut-il se décrire en une phrase?</li></ol><div class="tip custom-block"><p class="custom-block-title">En pratique</p><p>Commencer avec une organisation par fonctionnalité (CCP) et extraire des packages partagés (CRP) quand plusieurs fonctionnalités réutilisent les mêmes classes.</p></div>`,25))])}const q=n(c,[["render",u]]);export{f as __pageData,q as default};
